schedule_date = #{scheduleDate}, teacher_id = #{teacherId}, teacher_id = NULL, course_content = #{courseContent}, stage_name = #{stageName}, stage_name = NULL, schedule_type = #{scheduleType}, course_day_num = #{courseDayNum}, course_day_num = NULL, updated_at = now()
